function batchRepeatedMeshes(){const groups=[];world.traverse(o=>{if(o.isGroup)groups.push(o)});for(const g of groups){const buckets=new Map();for(const m of g.children){if(!m.isMesh||m.isInstancedMesh||!Array.from(geoCache.values()).includes(m.geometry))continue;const k=m.geometry.uuid+':'+m.material.uuid;if(!buckets.has(k))buckets.set(k,[]);buckets.get(k).push(m)}for(const list of buckets.values()){if(list.length<4)continue;const inst=new THREE.InstancedMesh(list[0].geometry,list[0].material,list.length);list.forEach((m,i)=>{m.updateMatrix();inst.setMatrixAt(i,m.matrix);g.remove(m)});inst.castShadow=true;inst.receiveShadow=true;inst.computeBoundingSphere();g.add(inst)}}}
function clearWorld(){if(selection){scene.remove(selection);selection.geometry.dispose();selection.material.dispose();selection=null}scene.remove(world);world.traverse(o=>{if(o.isInstancedMesh)o.dispose();if(o.geometry&&!Array.from(geoCache.values()).includes(o.geometry))o.geometry.dispose();if(o.material&&!Array.from(materials.values()).includes(o.material)&&!o.isSprite)o.material.dispose()});labels.forEach(l=>{l.tex.dispose();l.sm.dispose()});labels=[];pickables=[];explodeObjects=[];world=new THREE.Group();scene.add(world)}
function setExplode(v){explodeObjects.forEach(({obj,base,offset})=>obj.position.copy(base).addScaledVector(offset,v));if(selection)selection.update()}
function setScene(name){if(!builders[name])return;clearWorld();currentName=name;const cb=costBuilders({THREE,world,box,group,explode,pipe,ring,textLabel,floor,mat,palette});const pose=(cb[name]||builders[name])();batchRepeatedMeshes();baseCamera.set(...pose.slice(0,3));baseTarget.set(...pose.slice(3));camera.position.copy(baseCamera);controls.target.copy(baseTarget);controls.update();setExplode(Number(document.getElementById('explode').value)/100);renderer.render(scene,camera)}
function pick(e){const rect=canvas.getBoundingClientRect();const p=new THREE.Vector2((e.clientX-rect.left)/rect.width*2-1,-((e.clientY-rect.top)/rect.height)*2+1);const ray=new THREE.Raycaster();ray.setFromCamera(p,camera);const hits=ray.intersectObjects(pickables,true);for(const hit of hits){let o=hit.object;while(o&&o!==world){if(o.userData.term)return {term:o.userData.term,obj:o};o=o.parent}}return null}
function highlight(term){if(selection){scene.remove(selection);selection.geometry.dispose();selection.material.dispose();selection=null}const obj=pickables.find(o=>o.userData.term===term);if(obj){selection=new THREE.BoxHelper(obj,0xd5efab);selection.material.depthTest=false;selection.material.transparent=true;selection.material.opacity=.8;selection.renderOrder=6;scene.add(selection)}}
let pointerDown=null;canvas.addEventListener('pointerdown',e=>pointerDown={x:e.clientX,y:e.clientY,time:performance.now()});canvas.addEventListener('pointerup',e=>{if(!pointerDown||Math.hypot(e.clientX-pointerDown.x,e.clientY-pointerDown.y)>7||performance.now()-pointerDown.time>700)return;const hit=pick(e);if(hit){window.selectPart(hit.term,true);highlight(hit.term)}pointerDown=null});
const tip=document.getElementById('hover-label');canvas.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;const hit=pick(e);if(!hit){tip.style.display='none';canvas.style.cursor='grab';return}canvas.style.cursor='pointer';const t=window.TERMS.find(t=>t.id===hit.term);tip.textContent=t?.title||hit.term;tip.style.display='block';const rect=stage.getBoundingClientRect();tip.style.left=Math.max(5,Math.min(e.clientX-rect.left+15,rect.width-240))+'px';tip.style.top=Math.max(6,e.clientY-rect.top-38)+'px'});canvas.addEventListener('pointerleave',()=>tip.style.display='none');
window.addEventListener('scenechange',e=>{tip.style.display='none';setScene(e.detail)});window.addEventListener('explodechange',e=>setExplode(e.detail));window.addEventListener('partselect',e=>highlight(e.detail));
document.getElementById('reset-camera').addEventListener('click',()=>{camera.position.copy(baseCamera);controls.target.copy(baseTarget);controls.update()});function zoom(k){const offset=camera.position.clone().sub(controls.target);offset.setLength(THREE.MathUtils.clamp(offset.length()*k,controls.minDistance,controls.maxDistance));camera.position.copy(controls.target).add(offset);controls.update()}
document.getElementById('zoom-in').addEventListener('click',()=>zoom(.82));document.getElementById('zoom-out').addEventListener('click',()=>zoom(1.22));canvas.addEventListener('keydown',e=>{if(e.key==='+'||e.key==='='){zoom(.9);e.preventDefault()}else if(e.key==='-'){zoom(1.1);e.preventDefault()}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){const s=new THREE.Spherical().setFromVector3(camera.position.clone().sub(controls.target));s.theta+=(e.key==='ArrowLeft'?.13:e.key==='ArrowRight'?-.13:0);s.phi=THREE.MathUtils.clamp(s.phi+(e.key==='ArrowUp'?-.1:e.key==='ArrowDown'?.1:0),controls.minPolarAngle,controls.maxPolarAngle);camera.position.setFromSpherical(s).add(controls.target);controls.update();e.preventDefault()}});
